ALTER TABLE job_agent.application_package_revision ADD COLUMN review_status VARCHAR(30) NOT NULL DEFAULT 'NOT_READY', ADD COLUMN review_record_version BIGINT NOT NULL DEFAULT 0, ADD CONSTRAINT chk_application_revision_review_status CHECK(review_status IN ('NOT_READY','PENDING_REVIEW','CHANGES_REQUESTED','APPROVED_FOR_HANDOFF','REJECTED','INVALIDATED'));
UPDATE job_agent.application_package_revision SET review_status='PENDING_REVIEW' WHERE status='READY';
CREATE TABLE job_agent.application_review_decision(id UUID PRIMARY KEY,package_revision_id UUID NOT NULL REFERENCES job_agent.application_package_revision(id) ON DELETE RESTRICT,decision VARCHAR(30) NOT NULL CHECK(decision IN ('APPROVED_FOR_HANDOFF','CHANGES_REQUESTED','REJECTED')),actor_id VARCHAR(150) NOT NULL,actor_role VARCHAR(80) NOT NULL,review_comment VARCHAR(2000),checklist_snapshot JSONB NOT NULL,source_job_checksum CHAR(64) NOT NULL,source_profile_checksum CHAR(64) NOT NULL,source_evaluation_checksum CHAR(64) NOT NULL,artifact_manifest_checksum CHAR(64) NOT NULL,validation_snapshot_checksum CHAR(64) NOT NULL,created_at TIMESTAMPTZ NOT NULL,invalidated_at TIMESTAMPTZ,invalidation_reason VARCHAR(300));
CREATE INDEX idx_review_decision_revision_created ON job_agent.application_review_decision(package_revision_id,created_at DESC);
CREATE INDEX idx_application_revision_review_status ON job_agent.application_package_revision(review_status,created_at DESC);
